import { Effect } from "effect"
import type { Evidence } from "../domain/Evidence.js"
import { IncidentContext, type IncidentContext as IncidentContextType } from "../domain/IncidentContext.js"
import { decodePersisted } from "../domain/Common.js"
import { ContextContainsHypothesis, ContextEvidenceReferenceMissing } from "../errors/ContextErrors.js"
import { SchemaValidationFailed } from "../errors/DatasetErrors.js"
import { contextByteSize, validateContextBudget } from "./ContextBudget.js"

const forbiddenInferenceKeys = new Set(["hypothesis", "hypotheses", "rootcause", "rootcauses"])

const findForbiddenInferencePath = (value: unknown, path = "$", seen = new Set<unknown>()): string | undefined => {
  if (value === null || typeof value !== "object" || seen.has(value)) return undefined
  seen.add(value)
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const found = findForbiddenInferencePath(value[index], `${path}[${index}]`, seen)
      if (found !== undefined) return found
    }
    return undefined
  }
  for (const [key, child] of Object.entries(value)) {
    const normalized = key.replace(/[^a-z]/gi, "").toLowerCase()
    if (forbiddenInferenceKeys.has(normalized)) return `${path}.${key}`
    const found = findForbiddenInferencePath(child, `${path}.${key}`, seen)
    if (found !== undefined) return found
  }
  return undefined
}

export const decodeContext = (raw: unknown, path = "context.json") => {
  return Effect.gen(function* () {
    const forbiddenPath = findForbiddenInferencePath(raw)
    if (forbiddenPath !== undefined) yield* Effect.fail(new ContextContainsHypothesis({ path: forbiddenPath }))
    return yield* decodePersisted(IncidentContext)(raw).pipe(
      Effect.mapError(() => new SchemaValidationFailed({ path, reason: "Input does not match the strict IncidentContext contract" }))
    )
  })
}

export const referencedEvidenceIds = (context: IncidentContextType): ReadonlySet<string> => {
  const ids = new Set(context.evidenceReferences)
  for (const item of [...context.facts, ...context.recentChanges, ...context.errors, ...context.timeline, ...context.dependencies]) {
    for (const id of item.evidenceIds) ids.add(id)
  }
  return ids
}

export const validateContext = (
  raw: unknown,
  evidence: ReadonlyArray<Evidence>,
  maximumBytes?: number
): Effect.Effect<IncidentContextType, ContextContainsHypothesis | ContextEvidenceReferenceMissing | SchemaValidationFailed | import("../errors/ContextErrors.js").ContextBudgetExceeded> =>
  Effect.gen(function* () {
    const context = yield* decodeContext(raw)
    const knownIds = new Set(evidence.map((item) => item.id))
    for (const id of referencedEvidenceIds(context)) {
      if (!knownIds.has(id)) yield* Effect.fail(new ContextEvidenceReferenceMissing({ evidenceId: id }))
    }
    const declared = new Set(context.evidenceReferences)
    for (const collection of [context.facts, context.recentChanges, context.errors, context.timeline, context.dependencies]) {
      for (const item of collection) {
        for (const id of item.evidenceIds) {
          if (!declared.has(id)) yield* Effect.fail(new ContextEvidenceReferenceMissing({ evidenceId: id }))
        }
      }
    }
    yield* validateContextBudget(context, maximumBytes)
    return context
  })

const timelineEvidenceIdCount = (context: IncidentContextType): number => {
  const timelineEvidenceIds = new Set<string>()
  for (const event of context.timeline) {
    for (const id of event.evidenceIds) timelineEvidenceIds.add(id)
  }
  return timelineEvidenceIds.size
}

export const statsContext = (context: IncidentContextType): string => {
  const lines = [
    `Facts: ${context.facts.length}`,
    `Timeline events: ${context.timeline.length}`,
    `Errors: ${context.errors.length}`,
    `Dependencies: ${context.dependencies.length}`,
    `Timeline unique evidence IDs: ${timelineEvidenceIdCount(context)}`
  ]
  return `${lines.join("\n")}\n`
}

export const inspectContext = (context: IncidentContextType): string => {
  const lines = [
    `Incident: ${context.incident.id}`,
    `Service: ${context.incident.affectedService}`,
    `Environment: ${context.incident.environment}`,
    `Started: ${context.incident.startedAt}`,
    `Facts: ${context.facts.length}`,
    `Timeline events: ${context.timeline.length}`,
    `Timeline unique evidence IDs: ${timelineEvidenceIdCount(context)}`,
    `Recent changes: ${context.recentChanges.length}`,
    `Errors: ${context.errors.length}`,
    `Dependencies: ${context.dependencies.length}`,
    `Evidence references: ${context.evidenceReferences.length}`,
    `Canonical bytes: ${contextByteSize(context)}`
  ]
  return `${lines.join("\n")}\n`
}

import { readFile } from "node:fs/promises"
import { describe, expect, it } from "vitest"
import { Effect } from "effect"
import {
  decodeContext,
  inspectContext
} from "../../src/context/ContextValidator.js"

const fixture = async (name: string): Promise<unknown> =>
  JSON.parse(await readFile(new URL(`../../fixtures/synthetic-example/${name}`, import.meta.url), "utf8")) as unknown

describe("inspectContext", () => {
  it("reports deduplicated timeline evidence id count", async () => {
    const context = await Effect.runPromise(decodeContext(await fixture("context.json")))
    expect(inspectContext(context)).toContain("Timeline unique evidence IDs: 2")
  })

  it("deduplicates repeated evidence ids across timeline events", async () => {
    const raw = await fixture("context.json") as Record<string, unknown>
    const context = await Effect.runPromise(
      decodeContext({
        ...raw,
        timeline: [
          {
            timestamp: "2026-08-01T02:39:12Z",
            eventType: "deployment-started",
            subject: "checkout-api-v184",
            evidenceIds: ["ev-deploy-001", "ev-error-001"]
          },
          {
            timestamp: "2026-08-01T02:40:05Z",
            eventType: "error-observed",
            subject: "checkout-api",
            evidenceIds: ["ev-error-001"]
          }
        ]
      })
    )
    expect(inspectContext(context)).toContain("Timeline unique evidence IDs: 2")
  })
})

import { Data } from "effect"

export class ContextEvidenceReferenceMissing extends Data.TaggedError("ContextEvidenceReferenceMissing")<{
  readonly evidenceId: string
}> {}

export class ContextContainsHypothesis extends Data.TaggedError("ContextContainsHypothesis")<{
  readonly path: string
}> {}

export class ContextBudgetExceeded extends Data.TaggedError("ContextBudgetExceeded")<{
  readonly actualBytes: number
  readonly maximumBytes: number
}> {}

import { readFile } from "node:fs/promises"
import { describe, expect, it } from "vitest"
import { Effect, Schema } from "effect"
import { Incident } from "../../src/domain/Incident.js"
import { decodePersisted } from "../../src/domain/Common.js"
import { EvidenceCollection } from "../../src/domain/Evidence.js"
import { decodeContext, inspectContext, validateContext } from "../../src/context/ContextValidator.js"
import { contextByteSize, validateContextBudget } from "../../src/context/ContextBudget.js"

const fixture = async (name: string): Promise<unknown> =>
  JSON.parse(await readFile(new URL(`../../fixtures/synthetic-example/${name}`, import.meta.url), "utf8")) as unknown

const failureTag = async (effect: Effect.Effect<unknown, unknown>): Promise<string | undefined> => {
  const either = await Effect.runPromise(Effect.either(effect))
  return either._tag === "Left" && typeof either.left === "object" && either.left !== null && "_tag" in either.left
    ? String(either.left._tag)
    : undefined
}

describe("persisted schemas", () => {
  it("accepts the strict synthetic incident", async () => {
    const decoded = await Effect.runPromise(Schema.decodeUnknown(Incident)(await fixture("incident.json")))
    expect(decoded.id).toBe("synthetic-checkout-timeout")
  })

  it("rejects unknown persisted fields", async () => {
    const raw = { ...(await fixture("incident.json") as object), surprise: true }
    expect(await failureTag(decodePersisted(Incident)(raw))).toBe("ParseError")
  })

  it("rejects invalid and non-UTC timestamps", async () => {
    const raw = { ...(await fixture("incident.json") as Record<string, unknown>), startedAt: "2026-08-01 02:40:00" }
    expect(await failureTag(decodePersisted(Incident)(raw))).toBe("ParseError")
  })

  it("rejects unknown schema versions", async () => {
    const raw = { ...(await fixture("incident.json") as Record<string, unknown>), schemaVersion: "2.0" }
    expect(await failureTag(decodePersisted(Incident)(raw))).toBe("ParseError")
  })

  it("rejects missing context evidence references", async () => {
    const evidence = await Effect.runPromise(Schema.decodeUnknown(EvidenceCollection)(await fixture("evidence.json")))
    const context = await fixture("context.json") as Record<string, unknown>
    const broken = { ...context, evidenceReferences: ["ev-does-not-exist"] }
    expect(await failureTag(validateContext(broken, evidence))).toBe("ContextEvidenceReferenceMissing")
  })

  it("rejects explicitly named hypotheses and root cause fields", async () => {
    const context = await fixture("context.json") as Record<string, unknown>
    expect(await failureTag(decodeContext({ ...context, hypothesis: "deployment caused errors" }))).toBe("ContextContainsHypothesis")
    expect(await failureTag(decodeContext({ ...context, root_cause: "timeout" }))).toBe("ContextContainsHypothesis")
  })

  it("enforces the configured context byte budget", async () => {
    const context = await fixture("context.json")
    expect(await failureTag(validateContextBudget(context, 10))).toBe("ContextBudgetExceeded")
  })

  it("reports canonical byte size in inspect output", async () => {
    const context = await Effect.runPromise(decodeContext(await fixture("context.json")))
    const output = inspectContext(context)
    expect(output).toContain(`Canonical bytes: ${contextByteSize(context)}`)
  })
})

